/* ---------- game ---------- */
.game-screen { flex-direction: column; background: #060d12; }
.gamebar {
  display: flex; align-items: center; gap: 14px; height: 58px; padding: 0 14px;
  border-bottom: 1px solid var(--line); background: rgba(7,16,23,.94); flex-shrink: 0; z-index: 5;
}
.gamebar .brand-mark { width: 30px; height: 30px; font-size: 11px; border-radius: 7px; }
.job-id { min-width: 0; }
.job-id b { display: block; font-size: 11.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 260px; }
.job-id span { display: block; font-size: 8px; letter-spacing: .16em; color: var(--dim); text-transform: uppercase; }
.stage-track { display: flex; align-items: center; gap: 0; margin-left: auto; overflow-x: auto; scrollbar-width: none; }
.stage-track::-webkit-scrollbar { display: none; }
.stage-chip {
  display: flex; align-items: center; gap: 6px; padding: 7px 10px; font-size: 8.5px; font-weight: 700;
  letter-spacing: .1em; text-transform: uppercase; color: var(--dim); white-space: nowrap; position: relative;
}
.stage-chip i { width: 16px; height: 16px; border-radius: 50%; display: grid; place-items: center;
  border: 1px solid rgba(255,255,255,.16); font-style: normal; font-size: 7px; font-family: var(--mono); }
.stage-chip.done { color: #9fbfb3; }
.stage-chip.done i { background: rgba(125,211,167,.16); border-color: rgba(125,211,167,.45); color: var(--green); }
.stage-chip.active { color: var(--orange-2); }
.stage-chip.active i { background: var(--orange); border-color: var(--orange); color: #160e06; box-shadow: 0 0 16px rgba(255,122,26,.45); }
.stage-chip::after { content: ""; width: 14px; height: 1px; background: var(--line); margin-left: 4px; }
.stage-chip:last-child::after { display: none; }
.game-stats { display: flex; align-items: center; gap: 8px; margin-left: 8px; }
.stat-pill { display: flex; align-items: center; gap: 6px; padding: 6px 10px; border: 1px solid var(--line);
  border-radius: 7px; background: rgba(255,255,255,.025); font-family: var(--mono); font-size: 11px; }
.stat-pill small { font-family: var(--font); font-size: 8px; color: var(--dim); letter-spacing: .1em; }
.game-main { flex: 1; min-height: 0; display: flex; }
.stage-wrap { position: relative; flex: 1; min-width: 0; overflow: hidden; background: #0a151d; }
#game-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.stage-hud { position: absolute; inset: 12px 14px auto 14px; display: flex; gap: 10px; align-items: flex-start;
  justify-content: space-between; pointer-events: none; z-index: 3; }
.hud-cluster { display: flex; gap: 6px; flex-wrap: wrap; }
.hud-chip {
  background: rgba(7,16,23,.74); backdrop-filter: blur(10px); border: 1px solid rgba(164,195,214,.16);
  border-radius: 8px; padding: 6px 9px; min-width: 62px;
}
.hud-chip span { display: block; font-size: 7px; letter-spacing: .12em; text-transform: uppercase; color: var(--dim); }
.hud-chip b { display: block; font-family: var(--mono); font-size: 15px; line-height: 1.25; letter-spacing: -.02em; }
.hud-chip b small { font-size: 9px; color: var(--muted); }
.hud-chip.good b { color: var(--green); }
.hud-chip.warn b { color: var(--yellow); }
.hud-chip.bad b { color: var(--red); }
.hud-objective {
  max-width: 300px; padding: 8px 12px; border-radius: 9px; background: rgba(7,16,23,.78);
  backdrop-filter: blur(10px); border: 1px solid var(--line); font-size: 10.5px; line-height: 1.45; color: #b9cbd6;
}
.hud-objective b { display: block; font-size: 8px; letter-spacing: .15em; color: var(--orange-2); text-transform: uppercase; margin-bottom: 3px; }
.bar-stack { position: absolute; left: 14px; bottom: 12px; z-index: 3; display: grid; gap: 5px; width: 190px; pointer-events: none; }
.mini-bar { background: rgba(7,16,23,.72); border: 1px solid var(--line); border-radius: 6px; padding: 5px 7px; backdrop-filter: blur(8px); }
.mini-bar .lbl { display: flex; justify-content: space-between; font-size: 7.5px; letter-spacing: .09em; text-transform: uppercase; color: var(--dim); margin-bottom: 3px; }
.mini-bar .lbl b { font-family: var(--mono); color: var(--text); font-size: 8.5px; }
.track { height: 4px; border-radius: 3px; background: rgba(255,255,255,.1); overflow: hidden; position: relative; }
.track > i { display: block; height: 100%; border-radius: 3px; background: var(--green); transition: width .1s linear; }
.track.pressure { background: rgba(255,107,107,.16); }
.track .safe { position: absolute; top: 0; bottom: 0; background: rgba(125,211,167,.3); border-left: 1px solid rgba(125,211,167,.5); border-right: 1px solid rgba(125,211,167,.5); }
.warn-line { position: absolute; left: 50%; bottom: 62px; transform: translateX(-50%); z-index: 4; display: grid; gap: 6px; width: max-content; max-width: 80%; pointer-events: none; }
.warning {
  background: rgba(61,22,12,.9); border: 1px solid rgba(255,140,80,.45); color: #ffd2b3;
  border-radius: 7px; padding: 6px 11px; font-size: 10px; letter-spacing: .03em;
  display: flex; gap: 7px; align-items: center; animation: pulseWarn 1.4s infinite;
}
.warning.danger { background: rgba(70,14,14,.92); border-color: rgba(255,107,107,.6); color: #ffc4c4; }
@keyframes pulseWarn { 50% { opacity: .72; } }
.game-side { width: 294px; flex-shrink: 0; border-left: 1px solid var(--line); background: #09141c;
  display: flex; flex-direction: column; min-height: 0; }
.side-block { border-bottom: 1px solid var(--line); }
.side-title { display: flex; align-items: center; justify-content: space-between; padding: 12px 14px 9px;
  font-size: 8.5px; letter-spacing: .16em; text-transform: uppercase; color: var(--dim); }
.live-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--green); box-shadow: 0 0 8px var(--green); animation: blink 2s infinite; }
@keyframes blink { 50% { opacity: .25; } }
.crew-side { padding: 0 8px 10px; }
.crew-line { display: flex; align-items: center; gap: 8px; padding: 5px 6px; border-radius: 7px; transition: .2s; }
.crew-line.active { background: rgba(255,122,26,.1); box-shadow: inset 2px 0 0 var(--orange); }
.crew-line .avatar { width: 27px; height: 27px; border-radius: 7px; font-size: 9px; }
.crew-line .who { flex: 1; min-width: 0; }
.crew-line b { display: block; font-size: 10px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.crew-line span { display: block; font-size: 7.5px; color: var(--dim); text-transform: uppercase; letter-spacing: .08em; }
.crew-line .state { font-size: 7px; letter-spacing: .08em; color: var(--dim); text-transform: uppercase; text-align: right; }
.crew-line.active .state { color: var(--orange-2); }
.log-block { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.radio-log { flex: 1; overflow-y: auto; padding: 2px 12px 14px; display: flex; flex-direction: column; gap: 9px; }
.log-item { font-size: 10.5px; line-height: 1.45; color: #a9bcc8; animation: logIn .25s ease; }
.log-item .meta { display: flex; gap: 6px; align-items: center; margin-bottom: 2px; font-size: 7.5px; letter-spacing: .09em; text-transform: uppercase; }
.log-item .meta b { color: var(--role-color, var(--orange-2)); font-size: 8px; }
.log-item .meta time { color: var(--dim); font-family: var(--mono); }
.log-item.alert { color: #ffc4a6; }
.log-item.danger { color: #ffb3b3; }
.log-item.good { color: #b4e6ce; }
@keyframes logIn { from { opacity: 0; transform: translateY(4px); } }

.deck { flex-shrink: 0; border-top: 1px solid var(--line); background: linear-gradient(180deg, #0b1720, #081117);
  padding: 12px 16px calc(12px + env(safe-area-inset-bottom)); z-index: 6; max-height: 44vh; overflow-y: auto; }
.deck-inner { max-width: 1200px; margin: 0 auto; }

/* prep */
.prep-head { display: flex; justify-content: space-between; align-items: center; gap: 18px; margin-bottom: 10px; }
.prep-head h2 { font-size: 18px; letter-spacing: -.01em; text-transform: uppercase; }
.prep-head .sub { font-size: 10px; color: var(--dim); margin-top: 2px; }
.prep-steps { display: grid; grid-template-columns: repeat(5, 1fr); gap: 8px; }
.prep-step {
  position: relative; text-align: left; padding: 11px 12px; min-height: 88px; border-radius: 10px;
  border: 1px solid var(--line); background: rgba(255,255,255,.025); display: flex; flex-direction: column; gap: 3px;
